def edit(name,changes):
 s=(B/name).read_text('utf-8')
 for old,new in changes:
  assert old in s,(name,old[:80]);s=s.replace(old,new)
 (S/name).write_text(s,'utf-8')
 (U/(name+'.diff')).write_text(''.join(difflib.unified_diff((B/name).read_text('utf-8').splitlines(True),s.splitlines(True),fromfile='before/'+name,tofile='after/'+name)),'utf-8')
